# Analyze the demo to understand the rule, then apply to test input
def fill_interior(grid):
    """
    Fill interior cells with new color based on vertical boundary detection
    """
    n, m = grid.shape
    result = grid.copy()

    # Find all distinct colors in the grid
    colors = set()
    for r in range(n):
        for c in range(m):
            colors.add(grid[r, c])

    # Background is the most common color
    from collections import Counter
    all_values = [grid[r, c] for r in range(n) for c in range(m)]
    bg_color = Counter(all_values).most_common(1)[0][0]

    # Structure color (the color forming the walls)
    structure_color = None
    for c in colors:
        if c != bg_color:
            structure_color = c
            break

    # Now find the "hole" region - cells between vertical walls of structure color
    # that are separated by at least one row

    for r in range(n):
        for c in range(m):
            if grid[r, c] == bg_color:
                # Check if this is an interior cell
                # Look for structure color on left and right in the same row
                left_wall = False
                right_wall = False

                for side_c in range(c-1, -1, -1):
                    if grid[r, side_c] == structure_color:
                        left_wall = True
                        break
                    if grid[r, side_c] == bg_color and c == side_c + 1 and not any(
                            (grid[prev_r][prev_c] == grid[r, c] or 
                             grid[prev_r, prev_c] == structure_color) 
                            for prev_r in [r-1, r+1] for prev_c in [c] if prev_r >= 0 and prev_r < n:
                        ):
                        # There's a wall here
                        pass

                # Check if interior using the "gap" logic
                # A cell is interior if it's between vertical structure columns
                left_8 = False
                right_8 = False

                for check_c in range(c-1, -1, -1):
                    if grid[r, check_c] == bg_color:
                        pass
                    elif grid[r, check_c] == structure_color:
                        left_wall = True
                        break

                for check_c in range(c+1, m):
                    if grid[r, check_c] == bg_color:
                        pass
                    elif grid[r, check_c] == structure_color:
                        right_wall = True
                        break

                if left_wall and right_wall:
                    # Check for gaps above and below
                    gap_above = True
                    gap_below = True

                    for prev_r in [r-1]:
                        prev_row = grid[prev_r, c-2:c+3]  # check a window around the cell
                        has_8 = any(v == structure_color for v in prev_row)
                        if struct_color in prev_row:
