                        if prev_r < n:
                            prev_row = grid[prev_r, c-2:c+3]
                            has_8 = any(v == structure_color for v in prev_row)
                            if struct_color in prev_row:
                                gap_below = False
                                break

                    if gap_above and gap_below:
